package com.arslanca.orchestrai.business.abstracts.delivery;

import com.arslanca.orchestrai.business.dtos.delivery.DeliveryResult;
import com.arslanca.orchestrai.business.dtos.projectgeneration.BlueprintPlan;
import com.arslanca.orchestrai.entity.enums.IdeTarget;

/**
 * Interface for coordinating the delivery of blueprints to specific IDE
 * formats.
 */
public interface BlueprintDeliveryService {

    /**
     * Transforms the BlueprintPlan into an IDE-specific DeliveryResult.
     *
     * @param blueprint The payload generated by the LLM
     * @param ideTarget The target IDE selected by the user
     * @return The final delivery result ready to be streamed to the CLI
     */
    DeliveryResult deliver(BlueprintPlan blueprint, IdeTarget ideTarget);
}
